// Milestone-10 const-table acceptance: a 300-byte const (flash) table read
// through the two-entry chunked readers. Bytes 0..255 = 0x00..0xFF; bytes
// 256..299 = 0x11,0x12,...,0x3C (0x11 + (i-256)) — distinctive per-byte
// values, so a wrong chunk/window lands on the wrong RETLW (a readable
// wrong-answer, not a crash).
//
// Coverage (all runtime reads — see below):
//   - `table[in]`      in = 290 -> chunk 1 (0x33)      runtime chunk-1 read
//   - `table[in & 3]`  in = 290 -> table[2] = 0x02     runtime chunk-0 read
//   - `table[in + 9]`  in = 290 -> table[299] = 0x3C   chunk-1 LAST byte (const-299-equivalent)
//   - `table[in - 34]` in = 290 -> table[256] = 0x11   chunk boundary (chunk-1 first byte)
//
// Why no literal `table[299]` / `table[256]`: clang -O1 constant-folds a
// load from a const-initialized array at a constant index into a literal
// (`table[299]` -> `add i8 %v, 60`), so the read never reaches the IR —
// and if it did (gep with no terms), isel's large-table path panics
// ("constant index into large const table"), since only a single 16-bit
// reg index can select the chunk. The runtime-index forms above keep all
// four reads as genuine large-table reads at the exact boundary/edge
// indices the plan wanted (the 299 read lands on the last byte, the
// boundary read on byte 256).
//
// The `pad` filler (104 bytes) exists to push `table` past 0x100 into a
// nonzero 256-byte window — the reader's `MOVLW HIGH(table); MOVWF PCLATH`
// is then load-bearing (without it the computed PCL jump lands in window 0
// and every read returns a wrong byte). pad sorts before table (name
// order) so its table is emitted first. It is "used once" (`out =
// pad[in & 15]`) as a runtime read so clang -O1 cannot drop the global;
// its value (0xAA) is immediately overwritten by the next statement, so it
// does not affect the final `out`.
//
// Layout: main is 143 words, so goto (1) + main + __read_pad (6) puts pad
// at base 0x96 — pad is sized to fit its own window (0x96 + 104 = 0xFE <=
// 0x100) while still pushing table's natural base past 0x100; `.align 256`
// lifts the table to 0x200 (window 2): chunks at table/table_1 (LOW == 0
// both), total ends ~0x32C < 0x800.
//
// Expected for in == 290: out = (0x33 + 0x02 + 0x3C + 0x11) & 0xFF = 0x82
// (hand-traced against the emitted IR in const_table_e2e.rs).
volatile unsigned short in;          // 0x20-0x21: 16-bit index input
volatile unsigned char out;

const unsigned char pad[104] = {
    0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,
    0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,
    0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,
    0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,
    0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,
    0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,
    0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,
    0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,
    0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA,0xAA
};

const unsigned char table[300] = {
    0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0A,0x0B,
    0x0C,0x0D,0x0E,0x0F,0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17,
    0x18,0x19,0x1A,0x1B,0x1C,0x1D,0x1E,0x1F,0x20,0x21,0x22,0x23,
    0x24,0x25,0x26,0x27,0x28,0x29,0x2A,0x2B,0x2C,0x2D,0x2E,0x2F,
    0x30,0x31,0x32,0x33,0x34,0x35,0x36,0x37,0x38,0x39,0x3A,0x3B,
    0x3C,0x3D,0x3E,0x3F,0x40,0x41,0x42,0x43,0x44,0x45,0x46,0x47,
    0x48,0x49,0x4A,0x4B,0x4C,0x4D,0x4E,0x4F,0x50,0x51,0x52,0x53,
    0x54,0x55,0x56,0x57,0x58,0x59,0x5A,0x5B,0x5C,0x5D,0x5E,0x5F,
    0x60,0x61,0x62,0x63,0x64,0x65,0x66,0x67,0x68,0x69,0x6A,0x6B,
    0x6C,0x6D,0x6E,0x6F,0x70,0x71,0x72,0x73,0x74,0x75,0x76,0x77,
    0x78,0x79,0x7A,0x7B,0x7C,0x7D,0x7E,0x7F,0x80,0x81,0x82,0x83,
    0x84,0x85,0x86,0x87,0x88,0x89,0x8A,0x8B,0x8C,0x8D,0x8E,0x8F,
    0x90,0x91,0x92,0x93,0x94,0x95,0x96,0x97,0x98,0x99,0x9A,0x9B,
    0x9C,0x9D,0x9E,0x9F,0xA0,0xA1,0xA2,0xA3,0xA4,0xA5,0xA6,0xA7,
    0xA8,0xA9,0xAA,0xAB,0xAC,0xAD,0xAE,0xAF,0xB0,0xB1,0xB2,0xB3,
    0xB4,0xB5,0xB6,0xB7,0xB8,0xB9,0xBA,0xBB,0xBC,0xBD,0xBE,0xBF,
    0xC0,0xC1,0xC2,0xC3,0xC4,0xC5,0xC6,0xC7,0xC8,0xC9,0xCA,0xCB,
    0xCC,0xCD,0xCE,0xCF,0xD0,0xD1,0xD2,0xD3,0xD4,0xD5,0xD6,0xD7,
    0xD8,0xD9,0xDA,0xDB,0xDC,0xDD,0xDE,0xDF,0xE0,0xE1,0xE2,0xE3,
    0xE4,0xE5,0xE6,0xE7,0xE8,0xE9,0xEA,0xEB,0xEC,0xED,0xEE,0xEF,
    0xF0,0xF1,0xF2,0xF3,0xF4,0xF5,0xF6,0xF7,0xF8,0xF9,0xFA,0xFB,
    0xFC,0xFD,0xFE,0xFF,0x11,0x12,0x13,0x14,0x15,0x16,0x17,0x18,
    0x19,0x1A,0x1B,0x1C,0x1D,0x1E,0x1F,0x20,0x21,0x22,0x23,0x24,
    0x25,0x26,0x27,0x28,0x29,0x2A,0x2B,0x2C,0x2D,0x2E,0x2F,0x30,
    0x31,0x32,0x33,0x34,0x35,0x36,0x37,0x38,0x39,0x3A,0x3B,0x3C
};

void main(void) {
    out = pad[in & 15];                          // keep pad alive; value overwritten below
    out = table[in];                             // in = 290 -> chunk 1: table[290] = 0x33
    out = (unsigned char)(out + table[in & 3]);  // chunk 0: table[2] = 0x02
    out = (unsigned char)(out + table[in + 9]);  // chunk 1 last byte: table[299] = 0x3C
    out = (unsigned char)(out + table[in - 34]); // chunk boundary: table[256] = 0x11
}
